('as46', 'רוצה לעבוד במקום הכי נכון ברעננה? דרוש/ה סייע/ת שיניים לצוות מנצח', 'הזדמנות מקצועית: דרוש/ה סייע/ת לרופא/ת שיניים למרפאה מובילה ברעננה למרפאת שיניים יוקרתית ומשפחתית בעיר רעננה דרוש/ה סייע/ת לרופא שיניים הגדרת תפקיד: סייעת בחדר טיפול מרפאת שיניים יוקרתית ברעננה, המובלת על ידי צוות רופאות מהשורה הראשונה,…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/1000069945.png', 9, 1050, 3, 1, 'https://www.alldent.co.il/as46', 3, NULL, CURRENT_DATE, NOW()),
('doc71', 'רופא/ה שיניים למרפאה אורתודונטית ייחודית בנתניה', 'למרפאת שיניים ייחודית בנתניה העוסקת בתחום יישור השיניים דרוש רופא צעיר למרפאת שיניים שמתמחה בתחום יישור שינים דרוש/ה רופא שיניים הגדרות תפקיד: רופא עוזר אורתודנט תחומי טיפול עיקריים: ביצוע טיפולי יישור שיניים Invisalign. אורתודונטיה-…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/1000107229-5fce651e.jpg', 1, 809, 3, 2, 'https://www.alldent.co.il/doc71', 3, NULL, CURRENT_DATE, NOW()),
('doc69', 'דרוש/ה רופא/ת שיניים למרפאת מומחים בירושלים', 'דרוש/ה רופא/ת שיניים למרפאת מומחים פרטית בירושלים למרפאת מומחים איכותית ופרטית בירושלים דרוש/ה רופא/ת שיניים הגדרת תפקיד: רופא שיניים בחדר טיפולים למרפאת מומחים בתחום שיקום הפה דרוש/ה רופא/ה שיניים בעל יחסי אנוש מצויינים. המרפאה מבקשת…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/77035f6b8aab12a9c73a6f6e93969e5b_squeeze.jpg', 1, 474, 5, 2, 'https://www.alldent.co.il/doc69', 3, NULL, CURRENT_DATE, NOW()),
('se207', 'דרוש/ה מסלק/ת תביעות ביטוחי שיניים תפקיד עם אופק ניהולי ברמת-גן', 'דרוש/ה מסלק/ת תביעות ביטוחי שיניים תפקיד עם אופק ניהולי ברמת-גן לחברה דנטלית בצמיחה ברמת גן, דרוש/ה מסלק/ת תביעות ביטוחי שיניים. הגדרת התפקיד: ניהול וסילוק תביעות בתחום ביטוחי השיניים. בחינת צילומי שיניים (חובה!). מלאה - היברידית זמני…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/alldent2+%283%29-49a46cbc.jpg', 14, 1138, 1, 1, 'https://www.alldent.co.il/se207', 3, NULL, CURRENT_DATE, NOW()),
('adm44', 'דרוש/ה יועצ/ת מכירות לתחומי הדנטל והאסתטיקה ראשון-לציון', 'דרושה יועצ/ת טיפולים ומכירות למרכז רפואי מתקדם בראשון-לציון דרוש/ה איש/ת יועצ/ת מכירות וטיפולים למרכז רפואי מתקדם בראשון לציון מרפאת שיניים ותיקה ויציבה מעל 20 שנה, עוסקת בעיקר בשיקומי פה מורכבים (השתלות, כתרים) יחד עם אסתטיקת פנים…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/1000374286.jpg', 12, 1003, 14, 2, 'https://www.alldent.co.il/adm44', 3, NULL, CURRENT_DATE, NOW()),
('as204', 'סייעת לרופא שיניים למרפאת שיניים בשוהם', 'דרושה סייעת לרופא שיניים למרפאת שיניים בעיר שוהם לרשת שיניים בפריסה ארצית בסניף שוהם דרוש/ה סייע/ת לרופא שיניים הגדרת תפקיד: סייעת בחדרי טיפול זמני קבועה ומיידית היקף מלאה או חלקית ימים ושעות נדרשות: המרפאה עובדת ימים ראשון עד חמישי +…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/alldent1--286-29-1eb0cde8.jpg', 9, 1088, 14, 5, 'https://www.alldent.co.il/as204', 3, NULL, CURRENT_DATE, NOW()),
('se215', 'מזכירה איכותית למרפאת שיניים בשוהם', 'מזכירה איכותית למרפאת שיניים בשוהם לרשת שיניים בפריסה ארצית בסניף שוהם דרושה מזכירה למרפאה הגדרת תפקיד: מזכירה פרונטלית . התפקיד כולל עבודה מול חברות ביטוח, מעבדות שיניים, קביעת תורים, ניהול יומן רופא, גביית כספים ועוד זמני קבועה ומיידית…', 'https://irp.cdn-website.com/md/pexels/dms3rep/multi/pexels-photo-5355710.jpeg', 13, 1088, 14, 1, 'https://www.alldent.co.il/se215', 3, NULL, CURRENT_DATE, NOW()),
('adm40', 'משרה בכירה ומשפיעה: דרוש/ה מנהל/ת אזור לרשת מרפאות שיניים בפריסה רחבה', 'דרוש/ה מנהל/ת אזור (Area Manager) לרשת מרפאות מומחים בפריסה ארצית לרשת שיניים בפריסה ארצית דרוש/ה מנהל/ת אזור/מחוז על התפקיד: לרשת מרפאות שיניים יוקרתית וצומחת דרוש/ה מנהל/ת אזור בעל/ת שיעור קומה להובלת המערך התפעולי, הלוגיסטי והעסקי.…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/WhatsApp+Image+2026-02-23+at+11.47.29.jpeg', 12, NULL, NULL, 1, 'https://www.alldent.co.il/adm40', 3, NULL, CURRENT_DATE, NOW()),
('as59', 'סייעת למרפאת שיניים איכותית במודיעין', 'סייעת למרפאת שיניים איכותית בעיר מודיעין למרפאת שיניים איכותית במודיעין דרושה סייע/ת לרופא שיניים הגדרת תפקיד: סייעת בחדר טיפולים (עדיפות לסייעת כירורגית) מרכז רפואי דנטלי מתקדם הכולל צוות של 11 אנשי מקצוע הכולל סייעות, שינניות ורופאים…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/dent.as+%2815%29.jpg', 9, 627, 14, 2, 'https://www.alldent.co.il/as59', 3, NULL, CURRENT_DATE, NOW()),
('hy38', 'דרוש/ה שיננ/ית למרפאת שיניים בנהריה', 'שיננית איכותית למרפאת שיניים בעיר נהריה למרפאת שיניים בפריסה ארצית דרושה שיננית לסניף נהריה הגדרת תפקיד: שיננ/ית קלינית לחדר טיפולים פרקטיקה נדרשת: הסרת אבנית, ניקוי בהתזה, מתן ייעוץ והדרכה לבריאות השן הדרישה היא לשיננית מקצועית עם תודעת…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/%D7%97%D7%95%D7%A8%D7%99.jpeg', 10, 738, 12, 2, 'https://www.alldent.co.il/hy38', 3, NULL, CURRENT_DATE, NOW()),
('hy7', 'שיננית למרפאת שיניים בעיר באר-שבע', 'שיננית למרפאת שיניים בעיר באר-שבע למרפאת שיניים בפריסה ארצית דרושה שיננית לסניף באר-שבע זמני ההינה קבועה ומיידית היקף חלקית (1-2 משמרות בשבוע) ימים ושעות נדרשות: ימים גמישים לבחירה. משמרות בוקר וערב חובה! ניסיון מקצועי: מינימום שנה…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/21faca999a508358747de48d18f523839f-65191100c235f.jpeg', 10, 131, 8, 2, 'https://www.alldent.co.il/hy7', 3, NULL, CURRENT_DATE, NOW()),
('hy16', 'דרושה שיננית מקצועית למרפאה אורתודונטית בפתח-תקווה', 'דרושה שיננית חרוצה למרפאה אורתודונטית בפתח-תקווה *מיועדת לנשים וגברים כאחד למרפאת שיניים אורתודונטית ייחודית בפתח- תקווה דרושה שיננית הגדרת תפקיד: שיננית קלינית לחדר טיפולים הסרת אבנית, ניקוי בהתזה, לקיחת מטבעים לתבניות לימוד, מתן ייעוץ…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/imgi_1_pexels-photo-19879745.jpg', 10, 937, 6, 2, 'https://www.alldent.co.il/hy16', 3, NULL, CURRENT_DATE, NOW()),
('se109', 'הצטרפי לצוות שלנו! דרושה מזכירה דנטלית למרפאה פרטית בחולון', 'הצטרפי לצוות שלנו! דרושה מזכירה דנטלית למרפאה פרטית בחולון דרוש/ה מזכירה דנטלית מנוסה (דוברת רוסית) למרפאה רב-תחומית בחולון הגדרת תפקיד: מזכירה פרונטלית על המרפאה: מרכז דנטלי מתקדם ורב-תחומית הממוקם בחולון. המרפאה פועלת בסטנדרטים גבוהים…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/21img20231001wa0022-6518ff1c7252d.jpeg', 13, 375, 6, 2, 'https://www.alldent.co.il/se109', 3, NULL, CURRENT_DATE, NOW()),
