('hy4', 'שיננית מקצועית למרפאת מומחים בירושלים', 'שיננית מקצועית למרפאת מומחים בירושלים למרפאת שיניים איכותית ופרטית בירושלים דרוש/ה שיננ/ית הגדרת תפקיד: שיננ/ית קלינית לחדר טיפולים פרקטיקה נדרשת: הסרת אבנית, ניקוי בהתזה, מתן ייעוץ והדרכה לבריאות השן הדרישה היא לשיננית מקצועית עם תודעת…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/29d130e7f9a5ff622c3749299e73de561-63ffdcfa1960f-86fc8c79.jpeg', 10, 474, 5, 2, 'https://www.alldent.co.il/hy4', 3, NULL, CURRENT_DATE, NOW()),
('as206', 'סייעת איכותית למרפאת שיניים בחיפה', 'דרושה סייעת למרפאת שיניים בעיר חיפה לרשת שיניים בפריסה ארצית בסניף חיפה דרוש/ה סייע/ת לרופא שיניים הגדרת תפקיד: סייעת בחדרי טיפול זמני קבועה ומיידית היקף מלאה או חלקית ימים ושעות נדרשות: המרפאה עובדת ימים ראשון עד חמישי + שישי בוקר. חובה…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/21dd38f438f6122cc5a1dc130265ad0b41-651905ed81422.jpeg', 9, 388, 13, 5, 'https://www.alldent.co.il/as206', 3, NULL, CURRENT_DATE, NOW()),
